'use client';

// One thread at a page's foot (docs/specs/030-knowledgebase/page-comments.md "At the foot of the page"): a quiet card
// on the page's ground, its comments oldest first (the author's initials disc, name, when, "Edited", "Generated by
// AI", the words), then its foot: Reply and Resolve, or for a resolved thread "Resolved by Priya, 2 days ago" and
// Reopen. One's own comment has Edit and Delete, shown on hover or focus (always on touch); Delete asks first.
import { useState } from 'react';
import type { PageComment, PageThread, PageThreadChange } from '@liveknowledge/api-schema';
import {
  AiCommentMark,
  EditedCommentMark,
} from '@liveworkspace/workbench/components/comments/CommentMarks';
import {
  Button,
  ConfirmPopover,
  GlyphDisc,
  IDENTITY_FILL,
  Tooltip,
  identityVars,
} from '@liveknowledge/ui';
import { initialsOf } from '@/lib/identity';
import { relativeSince } from '@/lib/relative-time';
import {
  DeleteIcon,
  EditIcon,
  ReopenIcon,
  ResolveIcon,
} from '@/components/knowledge/approval/feedback-icons';
import { PageCommentComposer } from './PageCommentComposer';

type Change = (change: PageThreadChange) => Promise<boolean>;

const ROW_BUTTON =
  'flex size-7 cursor-pointer items-center justify-center rounded-md text-slate-400 transition hover:bg-slate-100 hover:text-slate-800 focus-visible:outline-2 focus-visible:outline-brand-600 motion-reduce:transition-none phone:size-11 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-slate-100';

function CommentItem({
  thread,
  comment,
  own,
  canWrite,
  now,
  change,
}: {
  thread: PageThread;
  comment: PageComment;
  own: boolean;
  canWrite: boolean;
  now: number;
  change: Change;
}) {
  const [editing, setEditing] = useState(false);
  const [confirm, setConfirm] = useState<HTMLElement | null>(null);
  const when = new Date(comment.createdAt).toLocaleString(undefined, {
    dateStyle: 'medium',
    timeStyle: 'short',
  });
  // A comment still on its way to the api has no id of its own yet: nothing to edit or delete.
  const mine = own && canWrite && !comment.id.startsWith('pending-');
  return (
    <li data-page-comment="" className="group flex gap-3 py-2.5 first:pt-0 last:pb-0">
      <GlyphDisc
        size={28}
        as="span"
        aria-hidden
        style={identityVars(comment.authorColor)}
        className={`mt-0.5 shrink-0 text-[11px] font-semibold text-white ${IDENTITY_FILL}`}
      >
        {initialsOf(comment.authorName)}
      </GlyphDisc>
      <div className="min-w-0 flex-1">
        <div className="flex min-h-7 items-center gap-1.5 text-[13px]">
          <span className="truncate font-medium text-slate-900 dark:text-slate-50">
            {comment.authorName}
          </span>
          <Tooltip label={when}>
            <time
              dateTime={new Date(comment.createdAt).toISOString()}
              tabIndex={0}
              className="shrink-0 text-xs text-slate-500 outline-none focus-visible:underline dark:text-slate-400"
            >
              {relativeSince(comment.createdAt, now)}
            </time>
          </Tooltip>
          {comment.editedAt ? <EditedCommentMark /> : null}
          {mine && !editing ? (
            <span className="ml-auto flex shrink-0 items-center gap-0.5 opacity-0 transition-opacity focus-within:opacity-100 group-hover:opacity-100 motion-reduce:transition-none [@media(hover:none)]:opacity-100">
              <Tooltip label="Edit">
                <button
                  type="button"
                  aria-label="Edit comment"
                  onClick={() => setEditing(true)}
                  className={ROW_BUTTON}
                >
                  <EditIcon />
                </button>
              </Tooltip>
              <Tooltip label="Delete">
                <button
                  type="button"
                  aria-label="Delete comment"
                  aria-haspopup="dialog"
                  onClick={(e) => setConfirm(e.currentTarget)}
                  className={`${ROW_BUTTON} hover:text-rose-700 dark:hover:text-rose-300`}
                >
                  <DeleteIcon />
                </button>
              </Tooltip>
            </span>
          ) : null}
        </div>
        {comment.ai ? <AiCommentMark /> : null}
        {editing ? (
          <div className="mt-1.5">
            <PageCommentComposer
              placeholder="Edit your comment..."
              submitLabel="Save"
              initial={comment.text}
              autoFocus
              onCancel={() => setEditing(false)}
              onSubmit={async (text) => {
                const done = await change({
                  op: 'edit',
                  thread: thread.id,
                  comment: comment.id,
                  text,
                });
                if (done) setEditing(false);
                return done;
              }}
            />
          </div>
        ) : (
          <p className="mt-0.5 whitespace-pre-wrap break-words text-sm leading-6 text-slate-700 dark:text-slate-200">
            {comment.text}
          </p>
        )}
      </div>
      {confirm ? (
        <ConfirmPopover
          anchor={confirm}
          message={
            thread.comments.length === 1
              ? 'Delete This Comment? The thread goes with it.'
              : 'Delete This Comment? It cannot be recovered.'
          }
          confirmLabel="Delete"
          onCancel={() => setConfirm(null)}
          onConfirm={() => {
            setConfirm(null);
            void change({ op: 'delete', thread: thread.id, comment: comment.id });
          }}
        />
      ) : null}
    </li>
  );
}

export function PageThreadCard({
  thread,
  ownKey,
  canWrite,
  now,
  change,
}: {
  thread: PageThread;
  ownKey: string | null;
  canWrite: boolean;
  now: number;
  change: Change;
}) {
  const [replying, setReplying] = useState(false);
  const pending = thread.id.startsWith('pending-');
  return (
    <article
      data-page-thread={thread.resolved ? 'resolved' : 'open'}
      aria-label={`Comment thread by ${thread.comments[0]?.authorName ?? 'someone'}`}
      className={`rounded-2xl border border-slate-200/80 bg-white/70 p-4 shadow-sm shadow-slate-900/[0.03] dark:border-slate-800 dark:bg-slate-900/60 ${
        thread.resolved ? 'opacity-70' : ''
      }`}
    >
      <ul className="flex flex-col divide-y divide-slate-100 dark:divide-slate-800/70">
        {thread.comments.map((comment) => (
          <CommentItem
            key={comment.id}
            thread={thread}
            comment={comment}
            own={ownKey !== null && comment.by === ownKey}
            canWrite={canWrite}
            now={now}
            change={change}
          />
        ))}
      </ul>
      {replying ? (
        <div className="mt-3 pl-10">
          <PageCommentComposer
            placeholder="Reply..."
            submitLabel="Reply"
            autoFocus
            onCancel={() => setReplying(false)}
            onSubmit={async (text) => {
              const done = await change({ op: 'reply', thread: thread.id, text });
              if (done) setReplying(false);
              return done;
            }}
          />
        </div>
      ) : (
        <footer className="mt-2 flex min-h-8 flex-wrap items-center gap-1 pl-10">
          {thread.resolved && thread.resolvedAt !== undefined ? (
            <span className="mr-auto text-xs text-slate-500 dark:text-slate-400">
              Resolved{thread.resolvedBy ? ` by ${thread.resolvedBy}` : ''},{' '}
              {relativeSince(thread.resolvedAt, now)}
            </span>
          ) : null}
          {canWrite && !pending ? (
            thread.resolved ? (
              <Button
                variant="ghost"
                size="xs"
                onClick={() => void change({ op: 'reopen', thread: thread.id })}
                className="cursor-pointer gap-1 phone:min-h-11"
              >
                <ReopenIcon />
                Reopen
              </Button>
            ) : (
              <>
                <Button
                  variant="ghost"
                  size="xs"
                  onClick={() => setReplying(true)}
                  className="cursor-pointer phone:min-h-11"
                >
                  Reply
                </Button>
                <Button
                  variant="ghost"
                  size="xs"
                  onClick={() => void change({ op: 'resolve', thread: thread.id })}
                  className="cursor-pointer gap-1 phone:min-h-11"
                >
                  <ResolveIcon />
                  Resolve
                </Button>
              </>
            )
          ) : null}
        </footer>
      )}
    </article>
  );
}
